{
  "name": "opencode-mnemoteca",
  "version": "0.3.0",
  "description": "OpenCode plugin for local persistent memory using Mnemoteca — offline semantic search, no cloud required",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "scripts": {
    "build": "tsc",
    "dev": "tsc --watch",
    "typecheck": "tsc --noEmit",
    "ci": "tsc --noEmit && tsc",
    "test": "tsc --noEmit -p tsconfig.test.json && tsx src/index.test.ts"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "mnemoteca",
    "memory",
    "local",
    "offline",
    "semantic-search",
    "ai",
    "coding-agent"
  ],
  "author": "gandazgul",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/gandazgul/opencode-mnemoteca.git"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.2.24"
  },
  "devDependencies": {
    "@types/node": "^25.4.0",
    "typescript": "^5.9.3",
    "tsx": "^4.20.6"
  },
  "opencode": {
    "type": "plugin"
  },
  "files": [
    "dist"
  ]
}
